{
  "definition_simple": "持ち物や服につける名前や名札のこと。",
  "definition_standard": "衣服や所持品などに記された名前。また、名前そのものや名札。",
  "pos": "名詞",
  "semantic_class": "abstract",
  "sentences": [
    {
      "sentence": "持ち物には全部ネームを書いてください。",
      "tier": "T1"
    },
    {
      "sentence": "シャツの胸元にネームを入れた。",
      "tier": "T2"
    },
    {
      "sentence": "制服に自分のネームを刺繍してもらった。",
      "tier": "T2"
    },
    {
      "sentence": "プレゼントの万年筆にネームを刻印した。",
      "tier": "T3"
    },
    {
      "sentence": "子どもの通学かばんにネームを縫い付けた。",
      "tier": "T3"
    },
    {
      "sentence": "ホテルの従業員は胸元にネームを着けている。",
      "tier": "T4"
    },
    {
      "sentence": "ブランドのネームが織り込まれた上質なタグが付いている。",
      "tier": "T4"
    },
    {
      "sentence": "書類に記入する際は、略称ではなく正式なネームを用いてください。",
      "tier": "T5"
    },
    {
      "sentence": "退職記念として贈られた時計の裏に、感謝の言葉とネームが刻まれている。",
      "tier": "T5"
    },
    {
      "sentence": "職人の誇りを象徴するように、完成した工芸品には独自のネームが刻印される。",
      "tier": "T6"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "primary_collocate": "入れる",
  "collocation_distractors": [
    {
      "word": "結ぶ",
      "explanation": "「契約を結ぶ」など関係性の成立に使われる動詞であり、名入れや名札を指す「ネーム」とは共起しません。"
    },
    {
      "word": "覚える",
      "explanation": "記憶する対象として「名前を覚える」とは言いますが、外来語「ネーム」と直接結びついて「ネームを覚える」とは通常言いません。"
    },
    {
      "word": "呼ぶ",
      "explanation": "声を出して対象を称呼する際は「名前を呼ぶ」と言い、「ネームを呼ぶ」というコロケーションは不自然です。"
    }
  ],
  "collocation_wrong_collocate": "掛ける",
  "cloze_distractors": [
    {
      "word": "タイトル",
      "explanation": "作品や題名を意味する語であり、衣服などに個人の名入れを施す文脈では意味が通りません。"
    },
    {
      "word": "サイン",
      "explanation": "著名人の署名や合図を指す語であり、特注仕立てで名前を刺繍する「ネームを入れる」という定型的な表現には適合しません。"
    },
    {
      "word": "ラベル",
      "explanation": "貼り付ける荷札や商標ラベルを指しますが、動詞「入れる」と組み合わせて名入れ加工を指す語としては不自然です。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "初対面の挨拶で「私のネームは田中です」と自己紹介した。",
      "explanation": "対面の自己紹介で自分の名前を述べる際は「名前」または「氏名」を使うのが自然であり、単独の「ネーム」を名乗りとして使うのは語用論的に誤りです。"
    },
    {
      "sentence": "黒板に先生のネームが大きく書かれていた。",
      "explanation": "人物の呼称や表記を指して単純に用いる場合は和語の「名前」が適切であり、名札・刺繍・刻印などの文脈を伴わない状況で「ネーム」を用いるのは不自然です。"
    },
    {
      "sentence": "遠くから走ってくる友達のネームを大きな声で呼んだ。",
      "explanation": "相手を声に出して呼びかける動作には「名前を呼ぶ」を用い、文字化された記号や刻印のニュアンスが強い「ネーム」を呼格の対象として取ることはできません。"
    }
  ],
  "spot_incorrect": {
    "sentence": "万年筆の本体に、記念としてアルファベットでネームに彫ってもらった。",
    "error_description": "動作の直接の対象（目的語）を表す格助詞には「に」ではなく「を」を用いる必要があります。",
    "corrected_sentence": "万年筆の本体に、記念としてアルファベットでネームを彫ってもらった。"
  },
  "word_family_forms": [
    "ネーミング",
    "ネームバリュー"
  ],
  "word_family_fake_forms": [
    "ネーム的",
    "ネーム化",
    "ネーマー"
  ],
  "syn_ant_candidates": [
    {
      "word": "名前",
      "relation": "synonym"
    },
    {
      "word": "氏名",
      "relation": "synonym"
    },
    {
      "word": "名札",
      "relation": "synonym"
    },
    {
      "word": "匿名",
      "relation": "antonym"
    }
  ],
  "particle_candidates": [
    {
      "particle": "に",
      "correct": true,
      "explanation": "付加・刻印・刺繍を行う対象の場所（着点）を示す助詞として「に」が適切です。"
    },
    {
      "particle": "で",
      "correct": false,
      "explanation": "「で」は動作が行われる場所や手段を示し、「ネームを入れる」の追加先・定着先を示す格助詞としては誤りです。"
    },
    {
      "particle": "を",
      "correct": false,
      "explanation": "「胸元」は作用が施される位置であり、直接の目的語（ネーム）と混同して「胸元をネームを入れた」とするのは文法的に不成立です。"
    },
    {
      "particle": "へ",
      "correct": false,
      "explanation": "「へ」は空間的な移動の方向を示す助詞であり、加工や記入の帰着点を示す固定的なコロケーション「〜にネームを入れる」には適合しません。"
    }
  ]
}
